# Source for q/ae-care-contrast.js: Clinical care, Stress echo, Echo instrumentation, Contrast.
CC="Clinical care"; ST="Stress echo"; EI="Echo instrumentation"; CO="Contrast"
Q=[
# --- Clinical care: preparation and positioning ---
(CC,"For parasternal and apical views, the patient is usually positioned:","In the left lateral decubitus position",["Prone","Right lateral decubitus","Standing"],"Rolling left brings the heart forward against the chest wall and moves lung tissue aside.","F"),
(CC,"Subcostal views are best obtained with the patient:","Supine, with knees bent to relax the abdomen",["Prone","Sitting fully upright","In the left lateral position with arms raised"],"Bending the knees relaxes the abdominal muscles, and a held inspiration brings the heart down.","F"),
(CC,"Suprasternal notch views are easier when the patient is:","Supine with the neck extended, often with a pillow under the shoulders",["Prone","Sitting with the chin on the chest","In the right lateral position"],"Neck extension opens the notch for the transducer.","F"),
(CC,"Raising the patient's left arm above the head during apical and parasternal imaging helps by:","Widening the rib spaces",["Lowering the heart rate","Increasing venous return","Reducing ECG artifact"],"Wider intercostal spaces give a larger acoustic window.","F"),
(CC,"Before a TEE, the patient should usually have nothing by mouth for about:","4 to 6 hours",["30 minutes","24 hours","No restriction is needed"],"An empty stomach reduces the risk of aspiration during sedation.","F"),
(CC,"Before inserting a TEE probe, the team should:","Remove dentures, apply topical anesthetic and place a bite block",["Fill the stomach with water","Remove the ECG leads","Position the patient prone"],"The bite block protects the probe and the patient's teeth.","F"),
(CC,"After a TEE with topical throat anesthesia, the patient should not eat or drink until:","The gag reflex has returned, usually 1 to 2 hours",["The next morning","Immediately after the probe is removed","24 hours later"],"Swallowing before sensation returns risks aspiration.","F"),
(CC,"During a TEE under conscious sedation, the patient's vital signs monitored include:","Heart rate, blood pressure, oxygen saturation and level of consciousness",["Temperature only","Blood glucose only","No monitoring is needed"],"Sedation can depress breathing; have suction and oxygen ready.","F"),
(CC,"An absolute contraindication to TEE is:","Esophageal stricture, tumor or perforation",["Atrial fibrillation","Mitral regurgitation","Recent eating more than 8 hours ago"],"Probe passage could tear the esophagus. Esophageal varices and prior esophageal surgery are relative contraindications.","F"),
(CC,"Methemoglobinemia after TEE can be caused by:","Topical benzocaine spray",["Agitated saline","Lidocaine gel on the skin","ECG electrodes"],"Watch for cyanosis with low oxygen saturation that does not improve with oxygen. Treatment is methylene blue.","C"),
(CC,"A rare but serious complication of TEE is:","Esophageal perforation",["Pneumothorax","Hemolysis","Coarctation"],"Others include laryngospasm, bleeding, aspiration and arrhythmias.","F"),
(CC,"Normal adult resting heart rate is:","60 to 100 beats per minute",["30 to 50 beats per minute","100 to 140 beats per minute","150 to 180 beats per minute"],"Below 60 is bradycardia; above 100 is tachycardia.","F"),
(CC,"Normal adult resting respiratory rate is about:","12 to 20 breaths per minute",["4 to 8 breaths per minute","30 to 40 breaths per minute","50 breaths per minute"],"Increased rate can signal distress or heart failure.","F"),
(CC,"Normal oxygen saturation (SpO₂) at rest is about:","95% to 100%",["70% to 80%","85% to 90%","50%"],"Persistently below 90% needs attention.","F"),
(CC,"Normal adult blood pressure is below:","120/80 mmHg",["160/100 mmHg","140/100 mmHg","100/50 mmHg"],"Blood pressure should be recorded at the time of echo; it affects gradients, regurgitation and filling.","F"),
(CC,"Recording blood pressure during the echo is especially important when assessing:","Aortic stenosis, regurgitation and LV function",["The aortic root diameter only","The pericardium only","Nothing; BP never affects echo"],"Severe hypertension can change gradients, MR and AR severity, and diastolic patterns.","F"),
(CC,"A patient becomes pale, sweaty and faint while sitting up after the echo. The likely cause and response are:","A vasovagal reaction: lay the patient flat, raise the legs and call for help",["Anaphylaxis: give contrast","Normal: send the patient home","Stroke: give food"],"Monitor vital signs and stay with the patient.","F"),
(CC,"Which finding is a critical result to report to the physician immediately?","A dissection flap in the ascending aorta",["Trace tricuspid regurgitation","Normal LVEF","Mild LA enlargement"],"Others include tamponade, a large mobile thrombus, free wall rupture and new severe valve dysfunction.","F"),
(CC,"The sonographer's role in reporting is to:","Provide accurate measurements and a technical summary to the interpreting physician",["Give the final diagnosis to the patient","Prescribe treatment","Change the physician's report"],"The physician interprets and signs the final report.","F"),
(CC,"A patient with a latex allergy needs:","Latex-free gloves, probe covers and equipment",["No changes","Only a different gel","A sterile gown"],"Latex reactions range from rash to anaphylaxis.","F"),
(CC,"Proper body mechanics when moving a patient include:","Bending at the knees, keeping the back straight and getting help when needed",["Lifting with the back bent","Twisting while lifting","Moving heavy patients alone"],"Use slide boards and teamwork to prevent injury to staff and patients.","F"),
(CC,"Before a portable echo in the ICU, the sonographer should check:","Lines, tubes and drains, and the patient's ability to be repositioned",["The patient's dinner order","Only the room number","Nothing; ICU patients can't be moved"],"Coordinate with nursing staff before moving ventilated or unstable patients.","F"),
(CC,"A 'time-out' before an invasive procedure such as TEE confirms:","The correct patient, procedure and consent",["The patient's insurance","The sonographer's schedule","The machine's frame rate"],"It is part of the universal protocol for preventing errors.","F"),
(CC,"An intravenous line used for contrast should be:","Patent and flushed with saline before and after injection",["Clamped during injection","Used without checking","Placed in the leg only"],"Check the site for swelling or pain that could mean infiltration.","F"),
(CC,"If a patient refuses part of the exam, the sonographer should:","Respect the refusal, document it and inform the physician",["Continue anyway","Restrain the patient","End the patient relationship"],"Patients have the right to refuse care.","F"),
# --- Stress echo ---
(ST,"Target heart rate for stress echo is usually at least:","85% of the age-predicted maximum (220 − age)",["50% of the maximum","100 beats per minute for everyone","120% of the maximum"],"For a 60-year-old: (220 − 60) × 0.85 = 136 beats per minute.","F"),
(ST,"A 50-year-old's target heart rate for stress echo is about:","145 beats per minute",["170 beats per minute","120 beats per minute","100 beats per minute"],"(220 − 50) × 0.85 = 144.5.","F"),
(ST,"After treadmill exercise, post-stress images should be acquired:","Within 60 to 90 seconds of stopping",["After 10 minutes of rest","The next day","Only if the patient has symptoms"],"Wall motion abnormalities can resolve quickly as the heart rate falls.","F"),
(ST,"A normal response of the LV to stress is:","All segments become hyperdynamic and the cavity gets smaller",["A new wall motion abnormality","The LV dilates","No change in contraction"],"Ischemia shows as new or worsening wall motion abnormalities, sometimes with LV dilation.","F"),
(ST,"A dobutamine stress echo protocol typically:","Increases the dose in stages (5 to 40 µg/kg/min) and may add atropine to reach target heart rate",["Uses a single high dose only","Uses adenosine as the main agent","Does not need ECG monitoring"],"Stages usually last about 3 minutes, with imaging at each stage.","F"),
(ST,"A 'biphasic response' on dobutamine stress echo indicates:","Viable but ischemic myocardium: improvement at low dose, then worsening at high dose",["Normal myocardium","Scar with no response","Pericardial disease"],"This pattern predicts recovery after revascularization.","C"),
(ST,"Side effects of dobutamine can be reversed with:","A short-acting beta-blocker such as esmolol or metoprolol",["Atropine","More dobutamine","Agitated saline"],"Dobutamine is a beta-agonist, so beta-blockers counter it.","F"),
(ST,"An absolute contraindication to exercise stress testing is:","Acute myocardial infarction within the last 2 days",["Controlled hypertension","A history of a healed MI years ago","Mild mitral valve prolapse"],"Others include unstable angina, uncontrolled arrhythmia, severe symptomatic AS, acute PE and acute aortic dissection.","F"),
(ST,"A reason to stop a stress test early is:","A drop in systolic blood pressure of more than 10 mmHg with signs of ischemia",["Reaching 50% of target heart rate","Mild sweating","Normal hyperdynamic wall motion"],"Others: sustained ventricular tachycardia, moderate to severe angina, ST elevation and patient request.","F"),
(ST,"Stress echo is also used for valve disease to assess:","Changes in gradients and pulmonary pressure with exercise, such as in mitral stenosis",["Bicuspid valve anatomy only","Coronary origins","Endocarditis vegetations"],"Exercise can unmask symptoms and raised pressures not seen at rest.","F"),
(ST,"Bicycle stress echo has an advantage over treadmill because:","Images can be acquired during exercise at peak stress",["It doesn't raise heart rate","It needs no ECG","It is always safer"],"Supine bicycles let the sonographer image continuously while the patient pedals.","F"),
(ST,"A new wall motion abnormality in the anterior wall and apex during stress suggests disease in the:","Left anterior descending artery",["Right coronary artery","Left circumflex artery","Pulmonary artery"],"Match segments to coronary territories: LAD anterior/apex, RCA inferior, LCx lateral.","F"),
# --- Echo instrumentation ---
(EI,"To improve frame rate when imaging fast-moving valve leaflets, the sonographer should:","Narrow the sector and reduce depth",["Widen the sector","Increase depth","Add multiple focal zones"],"Higher frame rates capture brief events such as valve motion.","F"),
(EI,"The non-imaging CW (pencil) probe is especially useful for:","Recording peak aortic stenosis velocity from the right parasternal and suprasternal windows",["Measuring LV volumes","Assessing wall motion","Imaging the LA appendage"],"Its small footprint fits into narrow windows and it is very sensitive.","F"),
(EI,"Tissue Doppler settings differ from blood-flow Doppler by using:","Low gain, low scale and the wall filter turned off or low",["High gain and high wall filter","High scale only","CW Doppler"],"Myocardial motion is slow but strong, so the settings are reversed compared with blood flow.","F"),
(EI,"For speckle-tracking strain, the recommended frame rate is about:","40 to 80 frames per second",["5 to 10 frames per second","200 to 300 frames per second for all exams","Frame rate does not matter"],"Too low a frame rate misses motion; too high lowers line density and speckle quality.","C"),
(EI,"Stitching artifact in 3D full-volume acquisition is caused by:","Movement or irregular rhythm between the beats that are combined",["High gain","Low frequency","Using a phased array"],"Ask the patient to hold their breath and avoid acquiring during arrhythmia.","F"),
(EI,"A multiplane TEE probe rotates its imaging plane from:","0° to 180°",["0° to 45° only","90° to 360°","It doesn't rotate"],"For example, the mid-esophageal four-chamber view is near 0°, and the bicommissural mitral view is near 60°.","F"),
(EI,"Harmonic imaging in echo makes valves and walls look:","Thicker than with fundamental imaging",["Thinner","Unchanged","Invisible"],"Measure valve thickness carefully with harmonics on, as it can overestimate it.","C"),
(EI,"For an accurate peak velocity in spectral Doppler, the scale should be set so that:","The waveform fills most of the display without aliasing",["The signal is tiny at the bottom","The waveform is cut off at the top","The baseline is in the middle for every exam"],"Adjust scale and baseline so the envelope is large and clear.","F"),
(EI,"A sweep speed of 100 mm/s is used for:","Accurate timing measurements such as IVRT, PHT and deceleration time",["Showing respiratory variation over many beats","Reducing aliasing","Measuring the aortic root"],"Slower sweeps (25 to 50 mm/s) show respiratory variation in pericardial disease.","F"),
(EI,"Zoom on the LVOT before measuring its diameter is important because:","Small errors in diameter are squared in the area calculation",["Zoom reduces frame rate","It eliminates the need for Doppler","It improves Doppler alignment"],"Write zoom adds detail; read zoom only enlarges pixels.","F"),
(EI,"A critical finding the sonographer must recognize during TEE is:","Thrombus in the left atrial appendage before cardioversion",["Normal LA size","Lambl's excrescences","Trace MR"],"Cardioversion with LAA thrombus risks stroke.","F"),
(EI,"Reducing overall gain helps when:","Blood pools look grey and cavity borders are unclear",["The image is already dark","Doppler signals are weak","The frame rate is too low"],"Too much gain fills cavities with noise and hides endocardial borders.","F"),
# --- Agitated saline ---
(CO,"Agitated saline bubbles normally do not reach the left heart because:","They are trapped in the pulmonary capillaries",["They dissolve in the RA","They are too small to see","They only fill the coronary sinus"],"Bubbles in the left heart mean a right-to-left shunt.","F"),
(CO,"Bubbles appearing in the LA within 3 beats of RA opacification suggest:","An intracardiac shunt such as a PFO or ASD",["An intrapulmonary shunt","Normal findings","Mitral regurgitation"],"Bubbles arriving later (after about 3 to 5 beats) suggest an intrapulmonary shunt such as an arteriovenous malformation.","F"),
(CO,"The Valsalva maneuver is used during a bubble study to:","Briefly raise right atrial pressure on release, opening a PFO",["Lower heart rate","Increase LV pressure","Stop bubbles from forming"],"Inject saline, then release the strain as bubbles arrive in the RA.","F"),
(CO,"A 'negative contrast' effect in the RA next to the atrial septum suggests:","Left-to-right flow through an ASD washing out the bubbles",["A right-to-left shunt","Normal flow","Tricuspid stenosis"],"Unopacified blood from the LA enters the RA and clears the bubbles.","C"),
(CO,"A bubble study injected in the LEFT arm that opacifies the coronary sinus before the RA confirms:","Persistent left superior vena cava",["A PFO","An ASD","Normal anatomy"],"The left SVC drains into the coronary sinus, which becomes dilated.","F"),
(CO,"Agitated saline can also be used to:","Enhance a weak TR Doppler signal for estimating RV systolic pressure",["Opacify the LV cavity","Measure LVOT diameter","Assess wall motion in the LV"],"The bubbles strengthen the right-sided Doppler signal.","F"),
(CO,"Agitated saline is made by:","Mixing saline with a small amount of air (and sometimes blood) between two syringes",["Shaking contrast agent","Heating saline","Adding gel"],"Air should be kept small, and large bubbles removed, to avoid air embolism.","F"),
# --- Ultrasound enhancing agents ---
(CO,"Commercial ultrasound enhancing agents (UEAs) differ from agitated saline because they:","Have stable microbubbles that cross the lungs and opacify the left heart",["Stay in the right heart","Are made of air only","Are larger than red blood cells"],"They contain high-molecular-weight gases with a lipid, albumin or polymer shell.","F"),
(CO,"UEA microbubbles are typically:","Smaller than red blood cells, about 1 to 5 µm",["Larger than 50 µm","The size of platelets only","Visible to the eye"],"Their small size lets them pass through the pulmonary capillaries.","F"),
(CO,"Which is NOT an indication for an ultrasound enhancing agent?","Measuring the TR peak velocity in a patient with excellent images",["Poor endocardial visibility in two or more segments","Confirming an LV apical thrombus","Assessing apical HCM or noncompaction"],"UEAs are used when they will change the answer.","F"),
(CO,"Contrast imaging for LV opacification is done at a low mechanical index (about 0.2 or less) because:","High MI destroys the microbubbles",["Low MI raises heating","Low MI increases frame rate only","High MI improves opacification"],"Low-MI imaging lets bubbles oscillate and return strong nonlinear signals.","F"),
(CO,"Swirling contrast at the apex usually means:","Bubbles are being destroyed or contrast concentration is too low",["Too much contrast","A pericardial effusion","Normal opacification"],"Lower the MI, move the focus to the apex, or give more contrast.","F"),
(CO,"Attenuation (shadowing) of the basal segments during contrast imaging is caused by:","Too much contrast in the near field",["Too little contrast","A low MI","Normal LV function"],"The bright apical bubbles absorb the sound before it reaches deeper segments. Wait or reduce the infusion.","F"),
(CO,"High-MI 'flash' frames during contrast echo are used to:","Destroy bubbles so replenishment can be watched for myocardial perfusion",["Improve LV opacification","Measure gradients","Remove artifacts"],"The rate at which bubbles refill the myocardium reflects blood flow.","C"),
(CO,"After giving an ultrasound enhancing agent, the patient should be:","Monitored for hypersensitivity reactions, with resuscitation equipment available",["Sent home immediately with no monitoring","Asked to exercise","Given food"],"Serious cardiopulmonary reactions are rare but can occur, usually within 30 minutes.","F"),
(CO,"A known contraindication to a lipid-shelled perflutren agent is:","Known hypersensitivity to perflutren or polyethylene glycol (PEG)",["Atrial fibrillation","Prior echo","Mild MR"],"Always check allergy history before giving a UEA.","F"),
(CO,"Microbubbles produce strong harmonic signals because they:","Oscillate nonlinearly when struck by ultrasound",["Absorb all sound","Travel faster than tissue","Are electrically charged"],"Harmonic and pulse-inversion techniques use this to separate bubbles from tissue.","F"),
(CO,"Contrast can help confirm an LV pseudoaneurysm by showing:","Contrast filling the cavity through a narrow neck",["No filling of the cavity","A thick, bright wall","A filling defect inside the LV only"],"It also outlines the true borders of the LV cavity and wall.","C"),
(CO,"An LV apical thrombus on contrast echo appears as:","A filling defect that contrast does not enter",["An area that fills brightly with contrast","A swirling pattern","A bright ring"],"Contrast outlines the thrombus, separating it from near-field clutter.","F"),
(CO,"Contrast improves Doppler signals by:","Increasing the strength of backscatter from blood",["Raising the PRF","Lowering the frequency","Removing the need for alignment"],"This can help record weak signals such as aortic stenosis or TR jets.","F"),
(CO,"When using contrast, the focal zone is usually placed:","Near the mitral valve level or deeper, to avoid destroying bubbles at the apex",["Right at the apex","At the skin surface","It doesn't matter"],"Placing the focus deeper spreads acoustic pressure and reduces apical bubble destruction.","C"),
]
